export default JSON.parse(
  "{\n  \"workId\": \"xunzi\",\n  \"chapter\": {\n    \"id\": \"xunzi_ch-10\",\n    \"workId\": \"xunzi\",\n    \"order\": 10,\n    \"title\": \"富國\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 17,\n    \"passageIds\": [\n      \"xunzi_ch-10_p-1\",\n      \"xunzi_ch-10_p-2\",\n      \"xunzi_ch-10_p-3\",\n      \"xunzi_ch-10_p-4\",\n      \"xunzi_ch-10_p-5\",\n      \"xunzi_ch-10_p-6\",\n      \"xunzi_ch-10_p-7\",\n      \"xunzi_ch-10_p-8\",\n      \"xunzi_ch-10_p-9\",\n      \"xunzi_ch-10_p-10\",\n      \"xunzi_ch-10_p-11\",\n      \"xunzi_ch-10_p-12\",\n      \"xunzi_ch-10_p-13\",\n      \"xunzi_ch-10_p-14\",\n      \"xunzi_ch-10_p-15\",\n      \"xunzi_ch-10_p-16\",\n      \"xunzi_ch-10_p-17\",\n      \"xunzi_ch-10_p-18\",\n      \"xunzi_ch-10_p-19\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"性惡論\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"xunzi_ch-10_p-1\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 1,\n      \"canonicalText\": \"萬物同宇而異體，無宜而有用為人，數也。人倫並處，同求而異道，同欲而異知，生也。皆有可也，知愚同；所可異也，知愚分。埶同而知異，行私而無禍，縱欲而不窮，則民心奮而不可說也。如是，則知者未得治也；知者未得治，則功名未成也；功名未成，則羣眾未縣也；羣眾未縣，則君臣未立也。無君以制臣，無上以制下，天下害生縱欲。欲惡同物，欲多而物寡，寡則必爭矣。故百技所成，所以養一人也。而能不能兼技，人不能兼官。離居不相待則窮，羣居而無分則爭；窮者患也，爭者禍也，救患除禍，則莫若明分使羣矣。彊脅弱也，知懼愚也，民下違上，少陵長，不以德為政：如是，則老弱有失養之憂，而壯者有分爭之禍矣。事業所惡也，功利所好也，職業無分：如是，則人有樹事之患，而有爭功之禍矣。男女之合，夫婦之分，婚姻娉內，送逆無禮：如是，則人有失合之憂，而有爭色之禍矣。故知者為之分也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-1_s-1\",\n        \"xunzi_ch-10_p-1_s-2\",\n        \"xunzi_ch-10_p-1_s-3\",\n        \"xunzi_ch-10_p-1_s-4\",\n        \"xunzi_ch-10_p-1_s-5\",\n        \"xunzi_ch-10_p-1_s-6\",\n        \"xunzi_ch-10_p-1_s-7\",\n        \"xunzi_ch-10_p-1_s-8\",\n        \"xunzi_ch-10_p-1_s-9\",\n        \"xunzi_ch-10_p-1_s-10\",\n        \"xunzi_ch-10_p-1_s-11\",\n        \"xunzi_ch-10_p-1_s-12\",\n        \"xunzi_ch-10_p-1_s-13\",\n        \"xunzi_ch-10_p-1_s-14\",\n        \"xunzi_ch-10_p-1_s-15\",\n        \"xunzi_ch-10_p-1_s-16\",\n        \"xunzi_ch-10_p-1_s-17\",\n        \"xunzi_ch-10_p-1_s-18\",\n        \"xunzi_ch-10_p-1_s-19\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"萬物同宇而且異體，無宜而且有用為人，數啊。人倫並處，同求而且異道，同欲而且異知，生啊。皆有可啊，知愚同；所可異啊，知愚分。埶同而且知異，行私而且無禍，縱欲而且不窮，則民心奮而且不可說啊。如是，則知的人或事未得治啊；知的人或事未得治，則功名未成啊；功名未成，則羣眾未縣啊；羣眾未縣，則君臣未立啊。無君以制臣，無上以制下，天下害生縱欲。欲惡同物，欲多而且物寡，寡則必爭矣。所以百技所成，所以養一人啊。而且能不能兼技，人不能兼官。離居不相待則窮，羣居而且無分則爭；窮的人或事患啊，爭的人或事禍啊，救患除禍，則莫若明分使羣矣。彊脅弱啊，知懼愚啊，民下違上，少陵長，不以德行修養為政：如是，則老弱有失養的憂，而且壯的人或事有分爭的禍矣。事業所惡啊，功利所好啊，職業無分：如是，則人有樹事的患，而且有爭功的禍矣。男女的合，夫婦的分，婚姻娉內，送逆無禮道義正道道德行修養規程：如是，則人有失合的憂，而且有爭色的禍矣。所以知的人或事為的分啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「萬物同宇而異體，無宜而有用為人，數也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「萬」、「物」、「同」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「萬物同宇而異體無宜而有用為人數也人倫並處同求而異」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「人倫並處，同求而異道，同欲而異知，生也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 2,\n      \"canonicalText\": \"足國之道：節用裕民，而善臧其餘。節用以禮，裕民以政。彼裕民，故多餘。裕民則民富，民富則田肥以易，田肥以易則出實百倍。上以法取焉，而下以禮節用之，餘若丘山，不時焚燒，無所臧之。夫君子奚患乎無餘？故知節用裕民，則必有仁聖賢良之名，而且有富厚丘山之積矣。此無他故焉，生於節用裕民也。不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；上雖好取侵奪，猶將寡獲也。而或以無禮節用之，則必有貪利糾譑之名，而且有空虛窮乏之實矣。此無他故焉，不知節用裕民也。《康誥》曰：「弘覆乎天，若德裕乃身。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-2_s-1\",\n        \"xunzi_ch-10_p-2_s-2\",\n        \"xunzi_ch-10_p-2_s-3\",\n        \"xunzi_ch-10_p-2_s-4\",\n        \"xunzi_ch-10_p-2_s-5\",\n        \"xunzi_ch-10_p-2_s-6\",\n        \"xunzi_ch-10_p-2_s-7\",\n        \"xunzi_ch-10_p-2_s-8\",\n        \"xunzi_ch-10_p-2_s-9\",\n        \"xunzi_ch-10_p-2_s-10\",\n        \"xunzi_ch-10_p-2_s-11\",\n        \"xunzi_ch-10_p-2_s-12\",\n        \"xunzi_ch-10_p-2_s-13\",\n        \"xunzi_ch-10_p-2_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"足國的道：節用裕民，而且善臧他的餘。節用以禮正義道義道品德修養規程，裕民以政。彼裕民，所以多餘。裕民則民富，民富則田肥以易，田肥以易則出實百倍。上以國家典章法度取焉，而且下以禮正義道義道品德修養規程節用的，餘若丘山，不時焚燒，無所臧的。夫君子奚患乎無餘？所以知節用裕民，則必有仁愛慈悲之德聖賢良的名，而且且有富厚丘山的積矣。此無他所以焉，生於節用裕民啊。不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；上雖好取侵奪，猶將寡獲啊。而且或以無禮正義道義道品德修養規程節用的，則必有貪利糾譑的名，而且且有空虛窮乏的實矣。此無他所以焉，不知節用裕民啊。《康誥》說道：弘覆乎天，若品德修養裕乃身。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「足國之道：節用裕民，而善臧其餘」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「足」、「國」、「道」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「足國之道節用裕民而善臧其餘節用以禮裕民以政彼裕民」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「節用以禮，裕民以政」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 3,\n      \"canonicalText\": \"禮者，貴賤有等；長幼有差，貧富輕重皆有稱者也。故天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。德必稱位，位必稱祿，祿必稱用，由士以上則必以禮樂節之，眾庶百姓則必以法數制之。量地而立國，計利而畜民，度人力而授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂之稱數。故自天子通於庶人，事無大小多少，由是推之。故曰：「朝無幸位，民無幸生。」此之謂也。輕田野之賦，平關市之徵，省商賈之數，罕興力役，無奪農時，如是則國富矣。夫是之謂以政裕民。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-3_s-1\",\n        \"xunzi_ch-10_p-3_s-2\",\n        \"xunzi_ch-10_p-3_s-3\",\n        \"xunzi_ch-10_p-3_s-4\",\n        \"xunzi_ch-10_p-3_s-5\",\n        \"xunzi_ch-10_p-3_s-6\",\n        \"xunzi_ch-10_p-3_s-7\",\n        \"xunzi_ch-10_p-3_s-8\",\n        \"xunzi_ch-10_p-3_s-9\",\n        \"xunzi_ch-10_p-3_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"禮道義正道道德行修養規程的人或事，貴賤有等；長幼有差，貧富輕重皆有稱的人或事啊。所以天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。德行修養必稱位，位必稱祿，祿必稱用，由士以上則必以禮道義正道道德行修養規程樂節的，眾庶百姓則必以典章法度數制的。量地而且立國，計利而且畜民，度人力而且授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂的稱數。所以自天子通於庶人，事無大小多少，由是推的。所以說：朝無幸位，民無幸生。此的謂啊。輕田野的賦，平關市的徵，省商賈的數，罕興力役，無奪農時，如是則國富矣。這就是儒家所說的以政裕民。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「禮者，貴賤有等」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「禮」、「貴」、「賤」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「禮者貴賤有等長幼有差貧富輕重皆有稱者也故天子袾裷」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「長幼有差，貧富輕重皆有稱者也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 4,\n      \"canonicalText\": \"人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣。故無分者，人之大害也；有分者，天下之本利也；而人君者，所以管分之樞要也。故美之者，是美天下之本也；安之者，是安天下之本也；貴之者，是貴天下之本也。古者先王分割而等異之也，故使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，非特以為淫泰誇麗之聲，將以明仁之文，通仁之順也。故為之雕琢、刻鏤、黼黻文章，使足以辨貴賤而已，不求其觀；為之鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而已，不求其餘；為之宮室、臺榭，使足以避燥溼、養德、辨輕重而已，不求其外。《詩》曰：「雕琢其章，金玉其相，亹亹我王，綱紀四方。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-4_s-1\",\n        \"xunzi_ch-10_p-4_s-2\",\n        \"xunzi_ch-10_p-4_s-3\",\n        \"xunzi_ch-10_p-4_s-4\",\n        \"xunzi_ch-10_p-4_s-5\",\n        \"xunzi_ch-10_p-4_s-6\",\n        \"xunzi_ch-10_p-4_s-7\",\n        \"xunzi_ch-10_p-4_s-8\",\n        \"xunzi_ch-10_p-4_s-9\",\n        \"xunzi_ch-10_p-4_s-10\",\n        \"xunzi_ch-10_p-4_s-11\",\n        \"xunzi_ch-10_p-4_s-12\",\n        \"xunzi_ch-10_p-4_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人的生不能無羣，羣而且無分則爭，爭則亂，亂則窮矣。所以無分的人或事，人的大害啊；有分的人或事，天下的本利啊；而且人君的人或事，所以管分的樞要啊。所以美的的人或事，是美天下的本啊；安的的人或事，是安天下的本啊；貴的的人或事，是貴天下的本啊。古的人或事先王分割而且等異的啊，所以使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，絕不是特以為淫泰誇麗的聲，將以明仁愛之德的文，通仁愛之德的順啊。所以為的雕琢、刻鏤、黼黻文章，使足以辨貴賤而且已，不求他的觀；為的鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而且已，不求他的餘；為的宮室、臺榭，使足以避燥溼、養德行修養、辨輕重而且已，不求他的外。《詩》說道：雕琢他的章，金玉他的相，亹亹我王，綱紀四方。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「人」、「生」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「人之生不能無羣羣而無分則爭爭則亂亂則窮矣故無分者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故無分者，人之大害也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 5,\n      \"canonicalText\": \"若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫。故其知慮足以治之，其仁厚足以安之，其德音足以化之，得之則治，失之則亂。百姓誠賴其知也，故相率而為之勞苦以務佚之，以養其知也；誠美其厚也，故為之出死斷亡以覆救之，以養其厚也；誠美其德也，故為之雕琢、刻鏤、黼黻、文章以藩飾之，以養其德也。故仁人在上，百姓貴之如帝，親之如父母，為之出死斷亡而愉者，無它故焉，其所是焉誠美，其所得焉誠大，其所利焉誠多。《詩》曰：「我任我輦，我車我牛，我行既集，蓋雲歸哉！」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-5_s-1\",\n        \"xunzi_ch-10_p-5_s-2\",\n        \"xunzi_ch-10_p-5_s-3\",\n        \"xunzi_ch-10_p-5_s-4\",\n        \"xunzi_ch-10_p-5_s-5\",\n        \"xunzi_ch-10_p-5_s-6\",\n        \"xunzi_ch-10_p-5_s-7\",\n        \"xunzi_ch-10_p-5_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"至於談到那重色而且衣的，重味而且食的，重財物而且制的，合天下而且君的，絕不是特以為淫泰啊，固以為主天下，治萬變，材萬物，養萬民，兼制天下的人或事，為莫若仁愛之德人的善啊夫。所以他的知慮足以治的，他的仁愛之德厚足以安的，他的德行修養音足以化的，得的則治，失的則亂。百姓誠賴他的知啊，所以相率而且為的勞苦以務佚的，以養他的知啊；誠美他的厚啊，所以為的出死斷亡以覆救的，以養他的厚啊；誠美他的德行修養啊，所以為的雕琢、刻鏤、黼黻、文章以藩飾的，以養他的德行修養啊。所以仁愛之德人在上，百姓貴的如帝，親的如父母，為的出死斷亡而且愉的人或事，無它所以焉，他的所是焉誠美，他的所得焉誠大，他的所利焉誠多。《詩》說道：我任我輦，我車我牛，我行既集，蓋雲歸哉！此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「重」、「色」、「衣」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「若夫重色而衣之重味而食之重財物而制之合天下而君之」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故其知慮足以治之，其仁厚足以安之，其德音足以化之，得之則治，失之則亂」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 6,\n      \"canonicalText\": \"故曰：君子以德，小人以力；力者，德之役也。百姓之力，待之而後功；百姓之羣，待之而後和；百姓之財，待之而後聚；百姓之埶，待之而後安；百姓之壽，待之而後長；父子不得不親，兄弟不得不順，男女不得不歡。少者以長，老者以養。故曰：「天地生之，聖人成之。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-6_s-1\",\n        \"xunzi_ch-10_p-6_s-2\",\n        \"xunzi_ch-10_p-6_s-3\",\n        \"xunzi_ch-10_p-6_s-4\",\n        \"xunzi_ch-10_p-6_s-5\",\n        \"xunzi_ch-10_p-6_s-6\",\n        \"xunzi_ch-10_p-6_s-7\",\n        \"xunzi_ch-10_p-6_s-8\",\n        \"xunzi_ch-10_p-6_s-9\",\n        \"xunzi_ch-10_p-6_s-10\",\n        \"xunzi_ch-10_p-6_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以說：君子以德行修養，小人以力；力的人或事，德行修養的役啊。百姓的力，待的而且後功；百姓的羣，待的而且後和；百姓的財，待的而且後聚；百姓的埶，待的而且後安；百姓的壽，待的而且後長；父子不得不親，兄弟不得不順，男女不得不歡。少的人或事以長，老的人或事以養。所以說：天地生的，聖人成的。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「故曰：君子以德，小人以力」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「君」、「子」、「德」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故曰君子以德小人以力力者德之役也百姓之力待之而後」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「力者，德之役也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 7,\n      \"canonicalText\": \"今之世而不然：厚刀布之斂，以奪之財；重田野之賦，以奪之食；苛關市之徵，以難其事。不然而已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝之。百姓曉然皆知其汙漫暴亂，而將大危亡也。是以臣或弒其君，下或殺其上，粥其城，倍其節，而不死其事者，無他故焉，人主自取之。《詩》曰：「無言不讎，無德不報。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-7_s-1\",\n        \"xunzi_ch-10_p-7_s-2\",\n        \"xunzi_ch-10_p-7_s-3\",\n        \"xunzi_ch-10_p-7_s-4\",\n        \"xunzi_ch-10_p-7_s-5\",\n        \"xunzi_ch-10_p-7_s-6\",\n        \"xunzi_ch-10_p-7_s-7\",\n        \"xunzi_ch-10_p-7_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今的世而且不然：厚刀布的斂，以奪的財；重田野的賦，以奪的食；苛關市的徵，以難他的事。不然而且已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝的。百姓曉然皆知他的汙漫暴亂，而且將大危亡啊。是以臣或弒他的君，下或殺他的上，粥他的城，倍他的節，而且不死他的事的人或事，無他所以焉，人主自取的。《詩》說道：無言不讎，無德行修養不報。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「今之世而不然：厚刀布之斂，以奪之財」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「今」、「世」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「今之世而不然厚刀布之斂以奪之財重田野之賦以奪之食」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「重田野之賦，以奪之食」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-8\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 8,\n      \"canonicalText\": \"兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也。守時力民，進事長功，和齊百姓，使人不偷，是將率之事也。高者不旱，下者不水，寒暑和節，而五穀以時孰，是天之事也。若夫兼而覆之，兼而愛之，兼而制之，歲雖兇敗水旱，使百姓無凍餧之患，則是聖君賢相之事也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-8_s-1\",\n        \"xunzi_ch-10_p-8_s-2\",\n        \"xunzi_ch-10_p-8_s-3\",\n        \"xunzi_ch-10_p-8_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"兼足天下的道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶的事啊。守時力民，進事長功，和齊百姓，使人不偷，是將率的事啊。高的人或事不旱，下的人或事不水，寒暑和節，而且五穀以時孰，是天的事啊。至於談到那兼而且覆的，兼而且愛的，兼而且制的，歲雖兇敗水旱，使百姓無凍餧的患，則是聖君賢相的事啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「兼」、「足」、「天」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「兼足天下之道在明分掩地表畝刺屮殖穀多糞肥田是農夫」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「守時力民，進事長功，和齊百姓，使人不偷，是將率之事也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 9,\n      \"canonicalText\": \"墨子之言昭昭然為天下憂不足。夫不足非天下之公患也，特墨子之私憂過計也。今是土之生五穀也，人善治之，則畝數盆，一歲而再獲之。然後瓜桃棗李一本數以盆鼓；然後葷菜百疏以澤量；然後六畜禽獸一而剸車；黿、鼉、魚、鱉、鰍、鱣以時別，一而成羣；然後飛鳥、鳧、雁若煙海；然後昆蟲萬物生其間，可以相食養者，不可勝數也。夫天地之生萬物也，固有餘，足以食人矣；麻葛繭絲、鳥獸之羽毛齒革也，固有餘，足以衣人矣。夫有餘不足，非天下之公患也，特墨子之私憂過計也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-9_s-1\",\n        \"xunzi_ch-10_p-9_s-2\",\n        \"xunzi_ch-10_p-9_s-3\",\n        \"xunzi_ch-10_p-9_s-4\",\n        \"xunzi_ch-10_p-9_s-5\",\n        \"xunzi_ch-10_p-9_s-6\",\n        \"xunzi_ch-10_p-9_s-7\",\n        \"xunzi_ch-10_p-9_s-8\",\n        \"xunzi_ch-10_p-9_s-9\",\n        \"xunzi_ch-10_p-9_s-10\",\n        \"xunzi_ch-10_p-9_s-11\",\n        \"xunzi_ch-10_p-9_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"墨子的言昭昭然為天下憂不足。夫不足絕不是天下的公患啊，特墨子的私憂過計啊。今是土的生五穀啊，人善治的，則畝數盆，一歲而且再獲的。然後瓜桃棗李一本數以盆鼓；然後葷菜百疏以澤量；然後六畜禽獸一而且剸車；黿、鼉、魚、鱉、鰍、鱣以時別，一而且成羣；然後飛鳥、鳧、雁若煙海；然後昆蟲萬物生他的間，可以相食養的人或事，不可勝數啊。夫天地的生萬物啊，固有餘，足以食人矣；麻葛繭絲、鳥獸的羽毛齒革啊，固有餘，足以衣人矣。夫有餘不足，絕不是天下的公患啊，特墨子的私憂過計啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「墨子之言昭昭然為天下憂不足」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「墨」、「子」、「言」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「墨子之言昭昭然為天下憂不足夫不足非天下之公患也特」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「夫不足非天下之公患也，特墨子之私憂過計也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 10,\n      \"canonicalText\": \"天下之公患，亂傷之也。胡不嘗試相與求亂之者誰也？我以墨子之「非樂」也，則使天下亂；墨子之「節用」也，則使天下貧，非將墮之也，說不免焉。墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而非樂。若是則瘠，瘠則不足欲；不足欲則賞不行。墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。若是則不威；不威則罰不行。賞不行，則賢者不可得而進也；罰不行，則不肖者不可得而退也。賢者不可得而進也，不肖者不可得而退也，則能不能不可得而官也。若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為之衣褐帶索，嚽菽飲水，惡能足之乎？既以伐其本，竭其原，而焦天下矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-10_s-1\",\n        \"xunzi_ch-10_p-10_s-2\",\n        \"xunzi_ch-10_p-10_s-3\",\n        \"xunzi_ch-10_p-10_s-4\",\n        \"xunzi_ch-10_p-10_s-5\",\n        \"xunzi_ch-10_p-10_s-6\",\n        \"xunzi_ch-10_p-10_s-7\",\n        \"xunzi_ch-10_p-10_s-8\",\n        \"xunzi_ch-10_p-10_s-9\",\n        \"xunzi_ch-10_p-10_s-10\",\n        \"xunzi_ch-10_p-10_s-11\",\n        \"xunzi_ch-10_p-10_s-12\",\n        \"xunzi_ch-10_p-10_s-13\",\n        \"xunzi_ch-10_p-10_s-14\",\n        \"xunzi_ch-10_p-10_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"天下的公患，亂傷的啊。胡不嘗試相與求亂的的人或事誰啊？我以墨子的絕不是樂啊，則使天下亂；墨子的節用啊，則使天下貧，絕不是將墮的啊，說不免焉。墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而且絕不是樂。若是則瘠，瘠則不足欲；不足欲則賞不行。墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。若是則不威；不威則罰不行。賞不行，則賢的人或事不可得而且進啊；罰不行，則不肖的人或事不可得而且退啊。賢的人或事不可得而且進啊，不肖的人或事不可得而且退啊，則能不能不可得而且官啊。若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為的衣褐帶索，嚽菽飲水，惡能足的乎？既以伐他的本，竭他的原，而且焦天下矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「天下之公患，亂傷之也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「天」、「下」、「公」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「天下之公患亂傷之也胡不嘗試相與求亂之者誰也我以墨」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「胡不嘗試相與求亂之者誰也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 11,\n      \"canonicalText\": \"故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳；必將錭琢刻鏤，黼黻文章，以塞其目；必將芻豢稻粱，五味芬芳，以塞其口。然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒其心。使天下生民之屬，皆知己之所願欲之舉在是於也，故其賞行；皆知己之所畏恐之舉在是於也，故其罰威。賞行罰威，則賢者可得而進也，不肖者可得而退也，能不能可得而官也。若是則萬物得其宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧之。夫天下何患乎不足也？故儒術誠行，則天下大而富，使而功，撞鐘擊鼓而和。《詩》曰：「鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。既醉既飽，福祿來反。」此之謂也。故墨術誠行，則天下尚儉而彌貧，非鬥而日爭，勞苦頓萃，而愈無功，愀然憂戚非樂，而日不和。《詩》曰：「天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-11_s-1\",\n        \"xunzi_ch-10_p-11_s-2\",\n        \"xunzi_ch-10_p-11_s-3\",\n        \"xunzi_ch-10_p-11_s-4\",\n        \"xunzi_ch-10_p-11_s-5\",\n        \"xunzi_ch-10_p-11_s-6\",\n        \"xunzi_ch-10_p-11_s-7\",\n        \"xunzi_ch-10_p-11_s-8\",\n        \"xunzi_ch-10_p-11_s-9\",\n        \"xunzi_ch-10_p-11_s-10\",\n        \"xunzi_ch-10_p-11_s-11\",\n        \"xunzi_ch-10_p-11_s-12\",\n        \"xunzi_ch-10_p-11_s-13\",\n        \"xunzi_ch-10_p-11_s-14\",\n        \"xunzi_ch-10_p-11_s-15\",\n        \"xunzi_ch-10_p-11_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以先王聖人為的不然：知夫為人主上的人或事，不美不飾的不足以一民啊，不富不厚的不足以管下啊，不威不強的不足以禁暴勝悍啊，所以必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞他的耳；必將錭琢刻鏤，黼黻文章，以塞他的目；必將芻豢稻粱，五味芬芳，以塞他的口。然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒他的心。使天下生民的屬，皆知己的所願欲的舉在是於啊，所以他的賞行；皆知己的所畏恐的舉在是於啊，所以他的罰威。賞行罰威，則賢的人或事可得而且進啊，不肖的人或事可得而且退啊，能不能可得而且官啊。若是則萬物得他的宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧的。夫天下何患乎不足啊？所以儒術誠行，則天下大而且富，使而且功，撞鐘擊鼓而且和。《詩》說道：鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。既醉既飽，福祿來反。此的謂啊。所以墨術誠行，則天下尚儉而且彌貧，絕不是鬥而且日爭，勞苦頓萃，而且愈無功，愀然憂戚絕不是樂，而且日不和。《詩》說道：天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「先」、「王」、「聖」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故先王聖人為之不然知夫為人主上者不美不飾之不足以」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「必將錭琢刻鏤，黼黻文章，以塞其目」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 12,\n      \"canonicalText\": \"垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也。可以少頃得姦民之譽，然而非長久之道也；事必不就，功必不立，是姦治者也。傮然要時務民，進事長功，輕非譽而恬失民，事進矣，而百姓疾之，是又偷偏者也。徙壞墮落，必反無功。故垂事養譽，不可；以遂功而忘民，亦不可。皆姦道也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-12_s-1\",\n        \"xunzi_ch-10_p-12_s-2\",\n        \"xunzi_ch-10_p-12_s-3\",\n        \"xunzi_ch-10_p-12_s-4\",\n        \"xunzi_ch-10_p-12_s-5\",\n        \"xunzi_ch-10_p-12_s-6\",\n        \"xunzi_ch-10_p-12_s-7\",\n        \"xunzi_ch-10_p-12_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"垂事養民，拊循的，唲嘔的，冬日則為的饘粥，夏日則為的瓜麮，以偷取少頃的譽焉，是偷道啊。可以少頃得姦民的譽，然而且絕不是長久的道啊；事必不就，功必不立，是姦治的人或事啊。傮然要時務民，進事長功，輕絕不是譽而且恬失民，事進矣，而且百姓疾的，是又偷偏的人或事啊。徙壞墮落，必反無功。所以垂事養譽，不可；以遂功而且忘民，亦不可。皆姦道啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「垂」、「事」、「養」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「垂事養民拊循之唲嘔之冬日則為之饘粥夏日則為之瓜麮」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「可以少頃得姦民之譽，然而非長久之道也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 13,\n      \"canonicalText\": \"故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；而百姓皆愛其上，人歸之如流水，親之歡如父母，為之出死斷亡而愉者，無它故焉，忠信、調和、均辨之至也。故國君長民者，欲趨時遂功，則和調累解，速乎急疾；忠信均辨，說乎慶賞矣；必先脩正其在我者，然後徐責其在人者，威乎刑罰。三德者誠乎上，則下應之如景嚮，雖欲無明達，得乎哉！《書》曰：「乃大明服，惟民其力懋，和而有疾。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-13_s-1\",\n        \"xunzi_ch-10_p-13_s-2\",\n        \"xunzi_ch-10_p-13_s-3\",\n        \"xunzi_ch-10_p-13_s-4\",\n        \"xunzi_ch-10_p-13_s-5\",\n        \"xunzi_ch-10_p-13_s-6\",\n        \"xunzi_ch-10_p-13_s-7\",\n        \"xunzi_ch-10_p-13_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以古人為的不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；而且百姓皆愛他的上，人歸的如流水，親的歡如父母，為的出死斷亡而且愉的人或事，無它所以焉，忠信、調和、均辨的至啊。所以國君長民的人或事，欲趨時遂功，則和調累解，速乎急疾；忠信均辨，說乎慶賞矣；必先脩正他的在我的人或事，然後徐責他的在人的人或事，威乎刑罰。三德行修養的人或事誠乎上，則下應的如景嚮，雖欲無明達，得乎哉！《書》說道：乃大明服，惟民他的力懋，和而且有疾。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「古」、「人」、「為」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故古人為之不然使民夏不宛喝冬不凍寒急不傷力緩不後」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「而百姓皆愛其上，人歸之如流水，親之歡如父母，為之出死斷亡而愉者，無它故焉，忠信、調和、均辨之至也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 14,\n      \"canonicalText\": \"故不教而誅，則刑繁而邪不勝；教而不誅，則姦民不懲；誅而不賞，則勤厲之民不勸；誅賞而不類，則下疑俗險而百姓不一。故先王明禮義以壹之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。若是，故姦邪不作，盜賊不起，而化善者勸勉矣。是何邪？則其道易，其塞固，其政令一，其防表明。故曰：上一則下一矣，上二則下二矣。闢之若屮木枝葉必類本。此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-14_s-1\",\n        \"xunzi_ch-10_p-14_s-2\",\n        \"xunzi_ch-10_p-14_s-3\",\n        \"xunzi_ch-10_p-14_s-4\",\n        \"xunzi_ch-10_p-14_s-5\",\n        \"xunzi_ch-10_p-14_s-6\",\n        \"xunzi_ch-10_p-14_s-7\",\n        \"xunzi_ch-10_p-14_s-8\",\n        \"xunzi_ch-10_p-14_s-9\",\n        \"xunzi_ch-10_p-14_s-10\",\n        \"xunzi_ch-10_p-14_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以不教而且誅，則刑繁而且邪不勝；教而且不誅，則姦民不懲；誅而且不賞，則勤厲的民不勸；誅賞而且不類，則下疑俗險而且百姓不一。所以先王明禮道義正道道德行修養規程道義正道以壹的，致忠信以愛的，尚賢使能以次的，爵服慶賞以申重的，時他的事，輕他的任，以調齊的，潢然兼覆的，養長的，如保赤子。若是，所以姦邪不作，盜賊不起，而且化善的人或事勸勉矣。是何邪？則他的道易，他的塞固，他的政令一，他的防表明。所以說：上一則下一矣，上二則下二矣。闢的若屮木枝葉必類本。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「故不教而誅，則刑繁而邪不勝」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「不」、「教」、「誅」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故不教而誅則刑繁而邪不勝教而不誅則姦民不懲誅而不」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「教而不誅，則姦民不懲」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 15,\n      \"canonicalText\": \"不利而利之，不如利而後利之之利也。不愛而用之，不如愛而後用之之功也。利而後利之，不如利而不利者之利也。愛而後用之，不如愛而不用者之功也。利而不利也，愛而不用也者，取天下者也。利而後利之，愛而後用之者，保社稷者也。不利而利之，不愛而用之者，危國家者也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-15_s-1\",\n        \"xunzi_ch-10_p-15_s-2\",\n        \"xunzi_ch-10_p-15_s-3\",\n        \"xunzi_ch-10_p-15_s-4\",\n        \"xunzi_ch-10_p-15_s-5\",\n        \"xunzi_ch-10_p-15_s-6\",\n        \"xunzi_ch-10_p-15_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"不利而且利的，不如利而且後利的的利啊。不愛而且用的，不如愛而且後用的的功啊。利而且後利的，不如利而且不利的人或事的利啊。愛而且後用的，不如愛而且不用的人或事的功啊。利而且不利啊，愛而且不用啊的人或事，取天下的人或事啊。利而且後利的，愛而且後用的的人或事，保社稷的人或事啊。不利而且利的，不愛而且用的的人或事，危國家的人或事啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「不利而利之，不如利而後利之之利也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「不」、「利」、「利」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「不利而利之不如利而後利之之利也不愛而用之不如愛而」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「不愛而用之，不如愛而後用之之功也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 16,\n      \"canonicalText\": \"觀國之治亂臧否，至於疆易而端已見矣。其候繳支繚，其竟關之政盡察，是亂國已。入其境，其田疇穢，都邑露，是貪主已。觀其朝廷，則其貴者不賢；觀其官職，則其治者不能；觀其便嬖，則其信者不愨，是闇主已。凡主相臣下百吏之屬，其於貨財取與計數也，順孰盡察；其禮義節奏也，芒軔僈楛，是辱國已。其耕者樂田，其戰士安難，其百吏好法，其朝廷隆禮，其卿相調議，是治國已。觀其朝廷，則其貴者賢；觀其官職，則其治者能；觀其便嬖，則其信者愨，是明主已。凡主相臣下百吏之屬，其於貨財取與計數也，寬饒簡易；其於禮義節奏也，陵謹盡察，是榮國已。賢齊則其親者先貴，能齊則其故者先官，其臣下百吏，汙者皆化而脩，悍者皆化而願，躁者皆化而愨，是明主之功已。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-16_s-1\",\n        \"xunzi_ch-10_p-16_s-2\",\n        \"xunzi_ch-10_p-16_s-3\",\n        \"xunzi_ch-10_p-16_s-4\",\n        \"xunzi_ch-10_p-16_s-5\",\n        \"xunzi_ch-10_p-16_s-6\",\n        \"xunzi_ch-10_p-16_s-7\",\n        \"xunzi_ch-10_p-16_s-8\",\n        \"xunzi_ch-10_p-16_s-9\",\n        \"xunzi_ch-10_p-16_s-10\",\n        \"xunzi_ch-10_p-16_s-11\",\n        \"xunzi_ch-10_p-16_s-12\",\n        \"xunzi_ch-10_p-16_s-13\",\n        \"xunzi_ch-10_p-16_s-14\",\n        \"xunzi_ch-10_p-16_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"觀國的治亂臧否，至於疆易而且端已見矣。他的候繳支繚，他的竟關的政盡察，是亂國已。入他的境，他的田疇穢，都邑露，是貪主已。觀他的朝廷，則他的貴的人或事不賢；觀他的官職，則他的治的人或事不能；觀他的便嬖，則他的信的人或事不愨，是闇主已。凡主相臣下百吏的屬，他的於貨財取與計數啊，順孰盡察；他的禮道義正道道德行修養規程道義正道節奏啊，芒軔僈楛，是辱國已。他的耕的人或事樂田，他的戰士安難，他的百吏好典章法度，他的朝廷隆禮道義正道道德行修養規程，他的卿相調議，是治國已。觀他的朝廷，則他的貴的人或事賢；觀他的官職，則他的治的人或事能；觀他的便嬖，則他的信的人或事愨，是明主已。凡主相臣下百吏的屬，他的於貨財取與計數啊，寬饒簡易；他的於禮道義正道道德行修養規程道義正道節奏啊，陵謹盡察，是榮國已。賢齊則他的親的人或事先貴，能齊則他的所以的人或事先官，他的臣下百吏，汙的人或事皆化而且脩，悍的人或事皆化而且願，躁的人或事皆化而且愨，是明主的功已。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「觀國之治亂臧否，至於疆易而端已見矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「觀」、「國」、「治」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「觀國之治亂臧否至於疆易而端已見矣其候繳支繚其竟關」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「其候繳支繚，其竟關之政盡察，是亂國已」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 17,\n      \"canonicalText\": \"觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。下貧則上貧，下富則上富。故田野縣鄙者，財之本也；垣窌倉廩者，財之末也。百姓時和，事業得敘者，貨之源也；等賦府庫者，貨之流也。故明主必謹養其和，節其流，開其源，而時斟酌焉。潢然使天下必有餘，而上不憂不足。如是，則上下俱富，交無所藏之。是知國計之極也。故禹十年水，湯七年旱，而天下無菜色者，十年之後，年穀復孰，而陳積有餘。是無它故焉，知本末源流之謂也。故田野荒而倉廩實，百姓虛而府庫滿，夫是之謂國蹶。伐其本，竭其源，而並之其末，然而主相不知惡也，則其傾覆滅亡可立而待也。以國持之，而不足以容其身，夫是之謂至貧，是愚主之極也。將以取富而喪其國，將以取利而危其身，古有萬國，今有十數焉，是無它故焉，其所以失之一也。君人者亦可以覺矣。百里之國，足以獨立矣。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-17_s-1\",\n        \"xunzi_ch-10_p-17_s-2\",\n        \"xunzi_ch-10_p-17_s-3\",\n        \"xunzi_ch-10_p-17_s-4\",\n        \"xunzi_ch-10_p-17_s-5\",\n        \"xunzi_ch-10_p-17_s-6\",\n        \"xunzi_ch-10_p-17_s-7\",\n        \"xunzi_ch-10_p-17_s-8\",\n        \"xunzi_ch-10_p-17_s-9\",\n        \"xunzi_ch-10_p-17_s-10\",\n        \"xunzi_ch-10_p-17_s-11\",\n        \"xunzi_ch-10_p-17_s-12\",\n        \"xunzi_ch-10_p-17_s-13\",\n        \"xunzi_ch-10_p-17_s-14\",\n        \"xunzi_ch-10_p-17_s-15\",\n        \"xunzi_ch-10_p-17_s-16\",\n        \"xunzi_ch-10_p-17_s-17\",\n        \"xunzi_ch-10_p-17_s-18\",\n        \"xunzi_ch-10_p-17_s-19\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"觀國的強弱貧富有徵：上不隆禮道義正道道德行修養規程則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。下貧則上貧，下富則上富。所以田野縣鄙的人或事，財的本啊；垣窌倉廩的人或事，財的末啊。百姓時和，事業得敘的人或事，貨的源啊；等賦府庫的人或事，貨的流啊。所以明主必謹養他的和，節他的流，開他的源，而且時斟酌焉。潢然使天下必有餘，而且上不憂不足。如是，則上下俱富，交無所藏的。是知國計的極啊。所以禹十年水，湯七年旱，而且天下無菜色的人或事，十年的後，年穀復孰，而且陳積有餘。是無它所以焉，知本末源流的謂啊。所以田野荒而且倉廩實，百姓虛而且府庫滿，這就是儒家所說的國蹶。伐他的本，竭他的源，而且並的他的末，然而且主相不知惡啊，則他的傾覆滅亡可立而且待啊。以國持的，而且不足以容他的身，這就是儒家所說的至貧，是愚主的極啊。將以取富而且喪他的國，將以取利而且危他的身，古有萬國，今有十數焉，是無它所以焉，他的所以失的一啊。君人的人或事亦可以覺矣。百里的國，足以獨立矣。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「觀」、「國」、「強」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「觀國之強弱貧富有徵上不隆禮則兵弱上不愛民則兵弱已」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 18,\n      \"canonicalText\": \"凡攻人者，非以為名，則案以為利也；不然則忿之也。仁人之用國，將脩志意，正身行，伉隆高，致忠信，期文理。布衣紃屨之士誠是，則雖在窮閻漏屋，而王公不能與之爭名；以國載之，則天下莫之能隱匿也。若是則為名者不攻也。將闢田野，實倉廩，便備用，上下一心，三軍同力，與之遠舉極戰則不可；境內之聚也保固；視可，午其軍，取其將，若撥麷。彼得之，不足以藥傷補敗。彼愛其爪牙，畏其仇敵，若是則為利者不攻也。將脩大小強弱之義，以持慎之，禮節將甚文，珪璧將甚碩，貨賂將甚厚，所以說之者，必將雅文辯慧之君子也。彼苟有人意焉，夫誰能忿之？若是，則忿之者不攻也。為名者否，為利者否，為忿者否，則國安於盤石，壽於旗翼。人皆亂，我獨治；人皆危，我獨安；人皆喪失之，我按起而治之。故仁人之用國，非特將持其有而已也，又將兼人。《詩》曰：「淑人君子，其儀不忒；其儀不忒，正是四國。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-18_s-1\",\n        \"xunzi_ch-10_p-18_s-2\",\n        \"xunzi_ch-10_p-18_s-3\",\n        \"xunzi_ch-10_p-18_s-4\",\n        \"xunzi_ch-10_p-18_s-5\",\n        \"xunzi_ch-10_p-18_s-6\",\n        \"xunzi_ch-10_p-18_s-7\",\n        \"xunzi_ch-10_p-18_s-8\",\n        \"xunzi_ch-10_p-18_s-9\",\n        \"xunzi_ch-10_p-18_s-10\",\n        \"xunzi_ch-10_p-18_s-11\",\n        \"xunzi_ch-10_p-18_s-12\",\n        \"xunzi_ch-10_p-18_s-13\",\n        \"xunzi_ch-10_p-18_s-14\",\n        \"xunzi_ch-10_p-18_s-15\",\n        \"xunzi_ch-10_p-18_s-16\",\n        \"xunzi_ch-10_p-18_s-17\",\n        \"xunzi_ch-10_p-18_s-18\",\n        \"xunzi_ch-10_p-18_s-19\",\n        \"xunzi_ch-10_p-18_s-20\",\n        \"xunzi_ch-10_p-18_s-21\",\n        \"xunzi_ch-10_p-18_s-22\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"凡攻人的人或事，絕不是以為名，則案以為利啊；不然則忿的啊。仁愛之德人的用國，將脩志意，正身行，伉隆高，致忠信，期文理。布衣紃屨的士誠是，則雖在窮閻漏屋，而且王公不能與的爭名；以國載的，則天下莫的能隱匿啊。若是則為名的人或事不攻啊。將闢田野，實倉廩，便備用，上下一心，三軍同力，與的遠舉極戰則不可；境內的聚啊保固；視可，午他的軍，取他的將，若撥麷。彼得的，不足以藥傷補敗。彼愛他的爪牙，畏他的仇敵，若是則為利的人或事不攻啊。將脩大小強弱的道義正道，以持慎的，禮道義正道道德行修養規程節將甚文，珪璧將甚碩，貨賂將甚厚，所以說的的人或事，必將雅文辯慧的君子啊。彼苟有人意焉，夫誰能忿的？若是，則忿的的人或事不攻啊。為名的人或事否，為利的人或事否，為忿的人或事否，則國安於盤石，壽於旗翼。人皆亂，我獨治；人皆危，我獨安；人皆喪失的，我按起而且治的。所以仁愛之德人的用國，絕不是特將持他的有而且已啊，又將兼人。《詩》說道：淑人君子，他的儀不忒；他的儀不忒，正是四國。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「凡攻人者，非以為名，則案以為利也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「凡」、「攻」、「人」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「凡攻人者非以為名則案以為利也不然則忿之也仁人之用」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「不然則忿之也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"order\": 19,\n      \"canonicalText\": \"持國之難易：事強暴之國難，使強暴之國事我易。事之以貨寶，則貨寶單，而交不結；約信盟誓，則約定而畔無日；割國之錙銖以賂之，則割定而欲無厭。事之彌煩，其侵人愈甚，必至於資單國舉然後已。雖左堯而右舜，未有能以此道得免焉者也。譬之是猶使處女嬰寶珠，佩寶玉，負戴黃金，而遇中山之盜也，雖為之逢蒙視，詘要撓膕，君盧屋妾，由將不足以免也。故非有一人之道也，直將巧繁拜請而畏事之，則不足以持國安身。故明君不道也。必將脩禮以齊朝，正法以齊官，平政以齊民；然後節奏齊於朝，百事齊於官，眾庶齊於下。如是，則近者競親，遠方致願，上下一心，三軍同力，名聲足以暴炙之，威強足以捶笞之，拱揖指揮，而強暴之國莫不趨使，譬之是猶烏獲與焦僥搏也。故曰：事強暴之國難，使強暴之國事我易。此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-10_p-19_s-1\",\n        \"xunzi_ch-10_p-19_s-2\",\n        \"xunzi_ch-10_p-19_s-3\",\n        \"xunzi_ch-10_p-19_s-4\",\n        \"xunzi_ch-10_p-19_s-5\",\n        \"xunzi_ch-10_p-19_s-6\",\n        \"xunzi_ch-10_p-19_s-7\",\n        \"xunzi_ch-10_p-19_s-8\",\n        \"xunzi_ch-10_p-19_s-9\",\n        \"xunzi_ch-10_p-19_s-10\",\n        \"xunzi_ch-10_p-19_s-11\",\n        \"xunzi_ch-10_p-19_s-12\",\n        \"xunzi_ch-10_p-19_s-13\",\n        \"xunzi_ch-10_p-19_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"持國的難易：事強暴的國難，使強暴的國事我易。事的以貨寶，則貨寶單，而且交不結；約信盟誓，則約定而且畔無日；割國的錙銖以賂的，則割定而且欲無厭。事的彌煩，他的侵人愈甚，必至於資單國舉然後已。雖左堯而且右舜，未有能以此道得免焉的人或事啊。譬的是猶使處女嬰寶珠，佩寶玉，負戴黃金，而且遇中山的盜啊，雖為的逢蒙視，詘要撓膕，君盧屋妾，由將不足以免啊。所以絕不是有一人的道啊，直將巧繁拜請而且畏事的，則不足以持國安身。所以明君不道啊。必將脩禮道義正道道德行修養規程以齊朝，正典章法度以齊官，平政以齊民；然後節奏齊於朝，百事齊於官，眾庶齊於下。如是，則近的人或事競親，遠方致願，上下一心，三軍同力，名聲足以暴炙的，威強足以捶笞的，拱揖指揮，而且強暴的國莫不趨使，譬的是猶烏獲與焦僥搏啊。所以說：事強暴的國難，使強暴的國事我易。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈富國〉。荀子立足於戰國後期的政治實踐，開篇「持國之難易：事強暴之國難，使強暴之國事我易」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「持」、「國」、「難」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「持國之難易事強暴之國難使強暴之國事我易事之以貨寶」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「事之以貨寶，則貨寶單，而交不結」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"萬物同宇而異體，無宜而有用為人，數也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"人倫並處，同求而異道，同欲而異知，生也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"皆有可也，知愚同；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"所可異也，知愚分。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"埶同而知異，行私而無禍，縱欲而不窮，則民心奮而不可說也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"如是，則知者未得治也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"知者未得治，則功名未成也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"功名未成，則羣眾未縣也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"羣眾未縣，則君臣未立也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"無君以制臣，無上以制下，天下害生縱欲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 11,\n      \"canonicalText\": \"欲惡同物，欲多而物寡，寡則必爭矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 12,\n      \"canonicalText\": \"故百技所成，所以養一人也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 13,\n      \"canonicalText\": \"而能不能兼技，人不能兼官。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 14,\n      \"canonicalText\": \"離居不相待則窮，羣居而無分則爭；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 15,\n      \"canonicalText\": \"窮者患也，爭者禍也，救患除禍，則莫若明分使羣矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 16,\n      \"canonicalText\": \"彊脅弱也，知懼愚也，民下違上，少陵長，不以德為政：如是，則老弱有失養之憂，而壯者有分爭之禍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 17,\n      \"canonicalText\": \"事業所惡也，功利所好也，職業無分：如是，則人有樹事之患，而有爭功之禍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 18,\n      \"canonicalText\": \"男女之合，夫婦之分，婚姻娉內，送逆無禮：如是，則人有失合之憂，而有爭色之禍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-1_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-1\",\n      \"order\": 19,\n      \"canonicalText\": \"故知者為之分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"足國之道：節用裕民，而善臧其餘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"節用以禮，裕民以政。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"彼裕民，故多餘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"裕民則民富，民富則田肥以易，田肥以易則出實百倍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"上以法取焉，而下以禮節用之，餘若丘山，不時焚燒，無所臧之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"夫君子奚患乎無餘？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"故知節用裕民，則必有仁聖賢良之名，而且有富厚丘山之積矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"此無他故焉，生於節用裕民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"不知節用裕民則民貧，民貧則田瘠以穢，田瘠以穢則出實不半；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"上雖好取侵奪，猶將寡獲也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"而或以無禮節用之，則必有貪利糾譑之名，而且有空虛窮乏之實矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"此無他故焉，不知節用裕民也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"《康誥》曰：「弘覆乎天，若德裕乃身。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-2_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"禮者，貴賤有等；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"長幼有差，貧富輕重皆有稱者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"故天子袾裷衣冕，諸侯玄裷衣冕，大夫裨冕，士皮弁服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"德必稱位，位必稱祿，祿必稱用，由士以上則必以禮樂節之，眾庶百姓則必以法數制之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"量地而立國，計利而畜民，度人力而授事，使民必勝事，事必出利，利足以生民，皆使衣食百用出入相揜，必時臧餘，謂之稱數。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"故自天子通於庶人，事無大小多少，由是推之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"故曰：「朝無幸位，民無幸生。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"輕田野之賦，平關市之徵，省商賈之數，罕興力役，無奪農時，如是則國富矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-3_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"夫是之謂以政裕民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"人之生不能無羣，羣而無分則爭，爭則亂，亂則窮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"故無分者，人之大害也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"有分者，天下之本利也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"而人君者，所以管分之樞要也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"故美之者，是美天下之本也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"安之者，是安天下之本也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"貴之者，是貴天下之本也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"古者先王分割而等異之也，故使或美，或惡，或厚，或薄，或佚或樂，或劬或勞，非特以為淫泰誇麗之聲，將以明仁之文，通仁之順也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"故為之雕琢、刻鏤、黼黻文章，使足以辨貴賤而已，不求其觀；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"為之鐘鼓、管磬、琴瑟、竽笙，使足以辨吉凶、合歡、定和而已，不求其餘；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"為之宮室、臺榭，使足以避燥溼、養德、辨輕重而已，不求其外。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"《詩》曰：「雕琢其章，金玉其相，亹亹我王，綱紀四方。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-4_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"若夫重色而衣之，重味而食之，重財物而制之，合天下而君之，非特以為淫泰也，固以為主天下，治萬變，材萬物，養萬民，兼制天下者，為莫若仁人之善也夫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"故其知慮足以治之，其仁厚足以安之，其德音足以化之，得之則治，失之則亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"百姓誠賴其知也，故相率而為之勞苦以務佚之，以養其知也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"誠美其厚也，故為之出死斷亡以覆救之，以養其厚也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"誠美其德也，故為之雕琢、刻鏤、黼黻、文章以藩飾之，以養其德也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"故仁人在上，百姓貴之如帝，親之如父母，為之出死斷亡而愉者，無它故焉，其所是焉誠美，其所得焉誠大，其所利焉誠多。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"《詩》曰：「我任我輦，我車我牛，我行既集，蓋雲歸哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-5_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"故曰：君子以德，小人以力；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"力者，德之役也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"百姓之力，待之而後功；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"百姓之羣，待之而後和；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"百姓之財，待之而後聚；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"百姓之埶，待之而後安；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"百姓之壽，待之而後長；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"父子不得不親，兄弟不得不順，男女不得不歡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"少者以長，老者以養。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"故曰：「天地生之，聖人成之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-6_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"今之世而不然：厚刀布之斂，以奪之財；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"重田野之賦，以奪之食；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"苛關市之徵，以難其事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"不然而已矣：有掎絜伺詐，權謀傾覆，以相顛倒，以靡敝之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"百姓曉然皆知其汙漫暴亂，而將大危亡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"是以臣或弒其君，下或殺其上，粥其城，倍其節，而不死其事者，無他故焉，人主自取之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"《詩》曰：「無言不讎，無德不報。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-7_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-8_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"兼足天下之道在明分：掩地表畝，刺屮殖穀，多糞肥田，是農夫眾庶之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-8_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"守時力民，進事長功，和齊百姓，使人不偷，是將率之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-8_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"高者不旱，下者不水，寒暑和節，而五穀以時孰，是天之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-8_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"若夫兼而覆之，兼而愛之，兼而制之，歲雖兇敗水旱，使百姓無凍餧之患，則是聖君賢相之事也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"墨子之言昭昭然為天下憂不足。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"夫不足非天下之公患也，特墨子之私憂過計也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"今是土之生五穀也，人善治之，則畝數盆，一歲而再獲之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"然後瓜桃棗李一本數以盆鼓；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"然後葷菜百疏以澤量；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"然後六畜禽獸一而剸車；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"黿、鼉、魚、鱉、鰍、鱣以時別，一而成羣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"然後飛鳥、鳧、雁若煙海；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"然後昆蟲萬物生其間，可以相食養者，不可勝數也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 10,\n      \"canonicalText\": \"夫天地之生萬物也，固有餘，足以食人矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 11,\n      \"canonicalText\": \"麻葛繭絲、鳥獸之羽毛齒革也，固有餘，足以衣人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-9_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-9\",\n      \"order\": 12,\n      \"canonicalText\": \"夫有餘不足，非天下之公患也，特墨子之私憂過計也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"天下之公患，亂傷之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"胡不嘗試相與求亂之者誰也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"我以墨子之「非樂」也，則使天下亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"墨子之「節用」也，則使天下貧，非將墮之也，說不免焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"墨子大有天下，小有一國，將蹙然衣粗食惡，憂戚而非樂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"若是則瘠，瘠則不足欲；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"不足欲則賞不行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"墨子大有天下，小有一國，將少人徒，省官職，上功勞苦，與百姓均事業，齊功勞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"若是則不威；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"不威則罰不行。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"賞不行，則賢者不可得而進也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"罰不行，則不肖者不可得而退也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 13,\n      \"canonicalText\": \"賢者不可得而進也，不肖者不可得而退也，則能不能不可得而官也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 14,\n      \"canonicalText\": \"若是，則萬物失宜，事變失應，上失天時，下失地利，中失人和，天下敖然，若燒若焦，墨子雖為之衣褐帶索，嚽菽飲水，惡能足之乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-10_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-10\",\n      \"order\": 15,\n      \"canonicalText\": \"既以伐其本，竭其原，而焦天下矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"故先王聖人為之不然：知夫為人主上者，不美不飾之不足以一民也，不富不厚之不足以管下也，不威不強之不足以禁暴勝悍也，故必將撞大鐘，擊鳴鼓，吹笙竽，彈琴瑟，以塞其耳；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"必將錭琢刻鏤，黼黻文章，以塞其目；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"必將芻豢稻粱，五味芬芳，以塞其口。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"然後眾人徒，備官職，漸慶賞，嚴刑罰，以戒其心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"使天下生民之屬，皆知己之所願欲之舉在是於也，故其賞行；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"皆知己之所畏恐之舉在是於也，故其罰威。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"賞行罰威，則賢者可得而進也，不肖者可得而退也，能不能可得而官也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"若是則萬物得其宜，事變得應，上得天時，下得地利，中得人和，則財貨渾渾如泉源，汸汸如河海，暴暴如丘山，不時焚燒，無所臧之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"夫天下何患乎不足也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"故儒術誠行，則天下大而富，使而功，撞鐘擊鼓而和。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"《詩》曰：「鐘鼓喤喤，管磬瑲瑲，降福穰穰，降福簡簡，威儀反反。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"既醉既飽，福祿來反。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 14,\n      \"canonicalText\": \"故墨術誠行，則天下尚儉而彌貧，非鬥而日爭，勞苦頓萃，而愈無功，愀然憂戚非樂，而日不和。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 15,\n      \"canonicalText\": \"《詩》曰：「天方薦瘥，喪亂弘多，民言無嘉，憯莫懲嗟。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-11_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-11\",\n      \"order\": 16,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"垂事養民，拊循之，唲嘔之，冬日則為之饘粥，夏日則為之瓜麮，以偷取少頃之譽焉，是偷道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"可以少頃得姦民之譽，然而非長久之道也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"事必不就，功必不立，是姦治者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"傮然要時務民，進事長功，輕非譽而恬失民，事進矣，而百姓疾之，是又偷偏者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"徙壞墮落，必反無功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"故垂事養譽，不可；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"以遂功而忘民，亦不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-12_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"皆姦道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"故古人為之不然：使民夏不宛喝，冬不凍寒，急不傷力，緩不後時，事成功立，上下俱富；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"而百姓皆愛其上，人歸之如流水，親之歡如父母，為之出死斷亡而愉者，無它故焉，忠信、調和、均辨之至也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"故國君長民者，欲趨時遂功，則和調累解，速乎急疾；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"忠信均辨，說乎慶賞矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"必先脩正其在我者，然後徐責其在人者，威乎刑罰。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"三德者誠乎上，則下應之如景嚮，雖欲無明達，得乎哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"《書》曰：「乃大明服，惟民其力懋，和而有疾。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-13_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"故不教而誅，則刑繁而邪不勝；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"教而不誅，則姦民不懲；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"誅而不賞，則勤厲之民不勸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"誅賞而不類，則下疑俗險而百姓不一。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"故先王明禮義以壹之，致忠信以愛之，尚賢使能以次之，爵服慶賞以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"若是，故姦邪不作，盜賊不起，而化善者勸勉矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"是何邪？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"則其道易，其塞固，其政令一，其防表明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"故曰：上一則下一矣，上二則下二矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 10,\n      \"canonicalText\": \"闢之若屮木枝葉必類本。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-14_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-14\",\n      \"order\": 11,\n      \"canonicalText\": \"此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"不利而利之，不如利而後利之之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"不愛而用之，不如愛而後用之之功也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"利而後利之，不如利而不利者之利也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"愛而後用之，不如愛而不用者之功也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"利而不利也，愛而不用也者，取天下者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"利而後利之，愛而後用之者，保社稷者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-15_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-15\",\n      \"order\": 7,\n      \"canonicalText\": \"不利而利之，不愛而用之者，危國家者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"觀國之治亂臧否，至於疆易而端已見矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"其候繳支繚，其竟關之政盡察，是亂國已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"入其境，其田疇穢，都邑露，是貪主已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"觀其朝廷，則其貴者不賢；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"觀其官職，則其治者不能；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"觀其便嬖，則其信者不愨，是闇主已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"凡主相臣下百吏之屬，其於貨財取與計數也，順孰盡察；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"其禮義節奏也，芒軔僈楛，是辱國已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 9,\n      \"canonicalText\": \"其耕者樂田，其戰士安難，其百吏好法，其朝廷隆禮，其卿相調議，是治國已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 10,\n      \"canonicalText\": \"觀其朝廷，則其貴者賢；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 11,\n      \"canonicalText\": \"觀其官職，則其治者能；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 12,\n      \"canonicalText\": \"觀其便嬖，則其信者愨，是明主已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 13,\n      \"canonicalText\": \"凡主相臣下百吏之屬，其於貨財取與計數也，寬饒簡易；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 14,\n      \"canonicalText\": \"其於禮義節奏也，陵謹盡察，是榮國已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-16_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-16\",\n      \"order\": 15,\n      \"canonicalText\": \"賢齊則其親者先貴，能齊則其故者先官，其臣下百吏，汙者皆化而脩，悍者皆化而願，躁者皆化而愨，是明主之功已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"觀國之強弱貧富有徵：上不隆禮則兵弱，上不愛民則兵弱，已諾不信則兵弱，慶賞不漸則兵弱，將率不能則兵弱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"上好功則國貧，上好利則國貧，士大夫眾則國貧，工商眾則國貧，無制數度量則國貧。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"下貧則上貧，下富則上富。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"故田野縣鄙者，財之本也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"垣窌倉廩者，財之末也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"百姓時和，事業得敘者，貨之源也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"等賦府庫者，貨之流也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 8,\n      \"canonicalText\": \"故明主必謹養其和，節其流，開其源，而時斟酌焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 9,\n      \"canonicalText\": \"潢然使天下必有餘，而上不憂不足。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 10,\n      \"canonicalText\": \"如是，則上下俱富，交無所藏之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 11,\n      \"canonicalText\": \"是知國計之極也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 12,\n      \"canonicalText\": \"故禹十年水，湯七年旱，而天下無菜色者，十年之後，年穀復孰，而陳積有餘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 13,\n      \"canonicalText\": \"是無它故焉，知本末源流之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 14,\n      \"canonicalText\": \"故田野荒而倉廩實，百姓虛而府庫滿，夫是之謂國蹶。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 15,\n      \"canonicalText\": \"伐其本，竭其源，而並之其末，然而主相不知惡也，則其傾覆滅亡可立而待也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 16,\n      \"canonicalText\": \"以國持之，而不足以容其身，夫是之謂至貧，是愚主之極也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 17,\n      \"canonicalText\": \"將以取富而喪其國，將以取利而危其身，古有萬國，今有十數焉，是無它故焉，其所以失之一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 18,\n      \"canonicalText\": \"君人者亦可以覺矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-17_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-17\",\n      \"order\": 19,\n      \"canonicalText\": \"百里之國，足以獨立矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"凡攻人者，非以為名，則案以為利也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"不然則忿之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"仁人之用國，將脩志意，正身行，伉隆高，致忠信，期文理。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"布衣紃屨之士誠是，則雖在窮閻漏屋，而王公不能與之爭名；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"以國載之，則天下莫之能隱匿也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"若是則為名者不攻也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"將闢田野，實倉廩，便備用，上下一心，三軍同力，與之遠舉極戰則不可；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"境內之聚也保固；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"視可，午其軍，取其將，若撥麷。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"彼得之，不足以藥傷補敗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 11,\n      \"canonicalText\": \"彼愛其爪牙，畏其仇敵，若是則為利者不攻也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 12,\n      \"canonicalText\": \"將脩大小強弱之義，以持慎之，禮節將甚文，珪璧將甚碩，貨賂將甚厚，所以說之者，必將雅文辯慧之君子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 13,\n      \"canonicalText\": \"彼苟有人意焉，夫誰能忿之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 14,\n      \"canonicalText\": \"若是，則忿之者不攻也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 15,\n      \"canonicalText\": \"為名者否，為利者否，為忿者否，則國安於盤石，壽於旗翼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 16,\n      \"canonicalText\": \"人皆亂，我獨治；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 17,\n      \"canonicalText\": \"人皆危，我獨安；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 18,\n      \"canonicalText\": \"人皆喪失之，我按起而治之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 19,\n      \"canonicalText\": \"故仁人之用國，非特將持其有而已也，又將兼人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 20,\n      \"canonicalText\": \"《詩》曰：「淑人君子，其儀不忒；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 21,\n      \"canonicalText\": \"其儀不忒，正是四國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-18_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-18\",\n      \"order\": 22,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"持國之難易：事強暴之國難，使強暴之國事我易。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"事之以貨寶，則貨寶單，而交不結；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"約信盟誓，則約定而畔無日；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"割國之錙銖以賂之，則割定而欲無厭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"事之彌煩，其侵人愈甚，必至於資單國舉然後已。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"雖左堯而右舜，未有能以此道得免焉者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 7,\n      \"canonicalText\": \"譬之是猶使處女嬰寶珠，佩寶玉，負戴黃金，而遇中山之盜也，雖為之逢蒙視，詘要撓膕，君盧屋妾，由將不足以免也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 8,\n      \"canonicalText\": \"故非有一人之道也，直將巧繁拜請而畏事之，則不足以持國安身。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 9,\n      \"canonicalText\": \"故明君不道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 10,\n      \"canonicalText\": \"必將脩禮以齊朝，正法以齊官，平政以齊民；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 11,\n      \"canonicalText\": \"然後節奏齊於朝，百事齊於官，眾庶齊於下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 12,\n      \"canonicalText\": \"如是，則近者競親，遠方致願，上下一心，三軍同力，名聲足以暴炙之，威強足以捶笞之，拱揖指揮，而強暴之國莫不趨使，譬之是猶烏獲與焦僥搏也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 13,\n      \"canonicalText\": \"故曰：事強暴之國難，使強暴之國事我易。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-10_p-19_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-10\",\n      \"passageId\": \"xunzi_ch-10_p-19\",\n      \"order\": 14,\n      \"canonicalText\": \"此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
